package net.minecraft.nbt;import java.util.*;public class CompoundTag extends Tag{public Map<String,Object> values=new HashMap<>();public CompoundTag getCompound(String k){return (CompoundTag)values.getOrDefault(k,new CompoundTag());}public void remove(String k){values.remove(k);}public int getInt(String k){return ((Number)values.getOrDefault(k,0)).intValue();}public void putInt(String k,int v){values.put(k,v);}public long getLong(String k){return ((Number)values.getOrDefault(k,0L)).longValue();}public void putLong(String k,long v){values.put(k,v);}public boolean getBoolean(String k){return Boolean.TRUE.equals(values.get(k));}public void putBoolean(String k,boolean v){values.put(k,v);}public String getString(String k){return (String)values.getOrDefault(k,"");}public void putString(String k,String v){values.put(k,v);}public boolean contains(String k){return values.containsKey(k);}public ListTag getList(String k,int type){return (ListTag)values.getOrDefault(k,new ListTag());}public Tag put(String k,Tag v){return (Tag)values.put(k,v);}public boolean hasUUID(String k){return values.get(k) instanceof UUID;}public UUID getUUID(String k){return (UUID)values.get(k);}public void putUUID(String k,UUID v){values.put(k,v);}}
